using System.Security.Cryptography;
using System.Text.Json;
using System.Text.Json.Nodes;
using CanDoItAll.AgentFramework.Core;
using CanDoItAll.AgentFramework.Models;
using CanDoItAll.AgentFramework.Persistence;
using Xunit.Abstractions;

namespace CanDoItAll.Tests.Integration.Runtime;

public sealed class ProcessIndexHistoricalBinaryHandoffProbe(ITestOutputHelper output) {
    private const string RootVariable = "CANDOITALL_PROCESS_INDEX_HANDOFF_ROOT";
    private const string RoleVariable = "CANDOITALL_PROCESS_INDEX_HANDOFF_ROLE";
    private const string PendingFile = "pending-run-detail-update.json";
    private const string SelectionStamp = "processSelectionRevision";
    private const string TargetTitle = "Original historical publication target";

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task Original_historical_binary_target_is_preserved(bool canonicalPublished) {
        var boundary = canonicalPublished ? ExistingRunDetailCommitStage.ExecutionIndexPersisted : ExistingRunDetailCommitStage.JournalPersisted;
        var root = Path.GetFullPath(Environment.GetEnvironmentVariable(RootVariable)
            ?? throw new InvalidOperationException("An explicitly owned handoff root is required."));
        Assert.True(Directory.Exists(root));
        var role = Enum.Parse<HandoffRole>(Environment.GetEnvironmentVariable(RoleVariable)
            ?? throw new InvalidOperationException("An explicit handoff role is required."));
        var workspace = Path.Combine(root, boundary.ToString());
        var receiptPath = Path.Combine(root, boundary + ".json");
        if (role == HandoffRole.Produce) {
            Assert.False(Directory.Exists(workspace));
            await using var fixture = await AgentToolAdmissionJournalFixture.CreateAsync();
            var run = fixture.Detail.Run with {
                Id = Guid.NewGuid(), ChatSessionId = null, ToolAdmission = null,
                ProcessRunId = Guid.NewGuid().ToString("D"), ProcessStepId = Guid.NewGuid().ToString("D"),
                SourceKind = "process-step", SourceId = "historical-binary-handoff"
            };
            await fixture.Store.SaveExecutionRunDetailAsync(new(run, null, [], []));
            var reached = false;
            var store = fixture.NewStore(stage => {
                if (stage == boundary) {
                    reached = true;
                    throw new IOException("Historical publication interruption.");
                }
            });
            await Assert.ThrowsAsync<IOException>(() => store.UpdateExecutionRunDetailAsync(run.Id,
                current => current with { Run = current.Run with { Revision = run.Revision + 1, Title = TargetTitle } }));
            Assert.True(reached);
            var layout = new FileSandboxWorkspaceStorageLayout(fixture.WorkspaceRoot, fixture.StorageScope);
            var pending = await File.ReadAllTextAsync(Path.Combine(layout.ExecutionStorageRoot, PendingFile));
            Assert.DoesNotContain(SelectionStamp, pending, StringComparison.OrdinalIgnoreCase);
            Assert.Contains(TargetTitle, pending, StringComparison.Ordinal);
            foreach (var file in Directory.EnumerateFiles(fixture.WorkspaceRoot, "*", SearchOption.AllDirectories)) {
                Assert.False(File.GetAttributes(file).HasFlag(FileAttributes.ReparsePoint));
                var relative = Path.GetRelativePath(fixture.WorkspaceRoot, file);
                var target = Path.GetFullPath(Path.Combine(workspace, relative));
                Assert.StartsWith(workspace + Path.DirectorySeparatorChar, target, StringComparison.Ordinal);
                Directory.CreateDirectory(Path.GetDirectoryName(target)!);
                File.Copy(file, target);
            }
            var files = Directory.EnumerateFiles(workspace, "*", SearchOption.AllDirectories)
                .ToDictionary(path => Path.GetRelativePath(workspace, path), Hash);
            var receipt = new HandoffReceipt(run.Id, Guid.Parse(run.ProcessRunId), run.Revision + 1, files);
            await File.WriteAllTextAsync(receiptPath, JsonSerializer.Serialize(receipt));
            output.WriteLine(JsonSerializer.Serialize(new { role, boundary, receipt.RunId, receipt.TargetRevision, fileCount = files.Count }));
            return;
        }
        Assert.Equal(HandoffRole.Consume, role);
        var original = JsonSerializer.Deserialize<HandoffReceipt>(await File.ReadAllTextAsync(receiptPath))!;
        foreach (var entry in original.Files) {
            Assert.Equal(entry.Value, Hash(Path.Combine(workspace, entry.Key)));
        }
        var currentStore = new FileSandboxWorkspaceStore(workspace, WorkspaceScopeDescriptor.Sandbox);
        var currentLayout = new FileSandboxWorkspaceStorageLayout(workspace, WorkspaceScopeDescriptor.Sandbox);
        Assert.Equal(ProcessExecutionRunPageStatus.PublicationPending,
            (await currentStore.ReadProcessExecutionRunPageAsync(new(original.ProcessRunId))).Status);
        var detail = (await currentStore.GetExecutionRunDetailAsync(original.RunId))!;
        Assert.Equal(original.TargetRevision, detail.Run.Revision);
        Assert.Equal(TargetTitle, detail.Run.Title);
        Assert.False(File.Exists(Path.Combine(currentLayout.ExecutionStorageRoot, PendingFile)));
        Assert.Null(JsonNode.Parse(await File.ReadAllTextAsync(currentLayout.ExecutionIndexPath))![SelectionStamp]);
        var page = await currentStore.ReadProcessExecutionRunPageAsync(new(original.ProcessRunId));
        Assert.Equal(original.TargetRevision, Assert.Single(page.Candidates).Revision);
        Assert.Equal(2, JsonNode.Parse(await File.ReadAllTextAsync(Path.Combine(currentLayout.ExecutionStorageRoot, "process-index.json")))!["schemaVersion"]!.GetValue<int>());
        await currentStore.UpdateExecutionRunDetailAsync(original.RunId,
            current => current with { Run = current.Run with { Revision = current.Run.Revision + 1 } });
        var canonical = JsonNode.Parse(await File.ReadAllTextAsync(currentLayout.ExecutionIndexPath))!;
        Assert.Equal(canonical["revision"]!.GetValue<long>(), canonical[SelectionStamp]!.GetValue<long>());
        output.WriteLine(JsonSerializer.Serialize(new { role, boundary, original.RunId, original.TargetRevision,
            originalFilesVerified = original.Files.Count, originalTargetRecovered = true, nextWriteInitializesSelection = true }));
    }

    private static string Hash(string path) => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)));
    private sealed record HandoffReceipt(Guid RunId, Guid ProcessRunId, long TargetRevision, Dictionary<string, string> Files);
    private enum HandoffRole { Produce, Consume }
}
